window.CODE = Object.assign(window.CODE || {}, {"ch22/agents.py":"\"\"\"A tiny agent class for this chapter, so the PATTERNS stay visible without any framework.\n\nAn agent here is: a name, a system prompt (its job and rules), and a run() that calls the model.\nChapter 9 added tools and a loop; frameworks in Chapters 23-25 add much more.\n\"\"\"\nimport sys\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent))\nfrom llm import achat, chat  # noqa: E402\n\n\n@dataclass\nclass Agent:\n    name: str\n    system: str\n    calls: int = 0\n\n    def run(self, task: str, max_tokens: int = 300) -> str:\n        self.calls += 1\n        return chat(task, system=self.system, temperature=0, max_tokens=max_tokens)[\"text\"].strip()\n\n    async def arun(self, task: str, max_tokens: int = 300) -> str:\n        self.calls += 1\n        return (await achat(task, system=self.system, temperature=0, max_tokens=max_tokens))[\"text\"].strip()\n\n\nRULES = \"Use only the facts given. Never give medical advice. One or two short sentences.\"\nFACTS = {\n    \"scheduling\": \"Dr Mehta: cardiology, Mon and Wed. Dr Rao: cardiology, Thu and Fri. Dr Iyer: orthopaedics, Tue and Thu. \"\n                \"Dr Khan: paediatrics, Mon, Tue and Fri.\",\n    \"billing\": \"OPD registration fee Rs 100, valid 7 days for the same doctor. ECG Rs 350. Refunds need billing-desk approval.\",\n    \"insurance\": \"PM-JAY, CGHS and the state scheme are accepted. Planned admissions need pre-authorisation 48 hours ahead. \"\n                 \"Consumables are not covered by PM-JAY.\",\n}\n\nscheduling = Agent(\"scheduling\", f\"You are the City Clinic scheduling desk. Facts: {FACTS['scheduling']} {RULES}\")\nbilling = Agent(\"billing\", f\"You are the City Clinic billing desk. Facts: {FACTS['billing']} {RULES}\")\ninsurance = Agent(\"insurance\", f\"You are the City Clinic insurance desk. Facts: {FACTS['insurance']} {RULES}\")\nSPECIALISTS = {a.name: a for a in (scheduling, billing, insurance)}\n","ch22/contracts.py":"\"\"\"Message contracts between agents: validated hand-offs and results, with Pydantic.\n\nFree text between agents is where details get lost or invented. A contract makes every hand-off\ncarry the same fields, rejects bad ones early, and keeps personal details out.\n\nRun:  python contracts.py\n\"\"\"\nimport re\nfrom typing import Literal\n\nfrom pydantic import BaseModel, Field, ValidationError, field_validator\n\nPHONE = re.compile(r\"\\b\\d{10}\\b\")\n\n\nclass Handoff(BaseModel):\n    run_id: str\n    from_agent: str\n    to_agent: Literal[\"scheduling\", \"billing\", \"insurance\"]\n    task: str = Field(min_length=10, max_length=400)\n    patient_ref: str = Field(pattern=r\"^UHID-\\d{4,}$\", description=\"An id, never a name or phone number\")\n    context: str = Field(\"\", max_length=600, description=\"A short summary, not the whole conversation\")\n\n    @field_validator(\"task\", \"context\")\n    @classmethod\n    def no_phone_numbers(cls, v: str) -> str:\n        if PHONE.search(v):\n            raise ValueError(\"contains a phone number; pass the UHID instead\")\n        return v\n\n\nclass Result(BaseModel):\n    run_id: str\n    agent: str\n    status: Literal[\"done\", \"needs_approval\", \"cannot_help\"]\n    answer: str\n    data: dict = {}\n\n\nif __name__ == \"__main__\":\n    ok = Handoff(run_id=\"run-42\", from_agent=\"supervisor\", to_agent=\"scheduling\",\n                 task=\"Find Dr Rao's next Thursday slot\", patient_ref=\"UHID-1001\")\n    print(\"valid:  \", ok.model_dump())\n    for bad in [dict(to_agent=\"pharmacy\"), dict(patient_ref=\"Asha Verma\"), dict(context=\"call her on 9876543210\")]:\n        try:\n            Handoff(**{**ok.model_dump(), **bad})\n        except ValidationError as e:\n            print(\"refused:\", \"; \".join(f\"{err['loc'][0]}: {err['msg']}\" for err in e.errors()))\n    print(\"result: \", Result(run_id=\"run-42\", agent=\"scheduling\", status=\"needs_approval\",\n                             answer=\"Thu 10:30 with Dr Rao is free; staff will confirm.\",\n                             data={\"slot\": \"Thu 10:30\"}).model_dump())\n","ch22/handoffs.py":"\"\"\"NETWORK / SWARM pattern: peers hand work to each other directly, with no supervisor.\n\nEach desk either answers, or replies  HANDOFF: <desk> | <short note for that desk>.\nThe conversation moves to whoever was named. A guard stops loops (Chapter 21).\n\nRun:  python handoffs.py\n\"\"\"\nimport sys\nfrom pathlib import Path\n\nfrom agents import FACTS, RULES, Agent\n\nsys.path.insert(0, str(Path(__file__).resolve().parent.parent / \"ch21\"))\nfrom failure_guards import RunGuard, StopRun  # noqa: E402\n\nPEERS = \"Other desks: scheduling, billing, insurance.\"\nHANDOFF_RULE = (\"If the request belongs to another desk, reply exactly: HANDOFF: <desk> | <one-line note for that desk>. \"\n                \"Otherwise answer it.\")\ndesks = {name: Agent(name, f\"You are the City Clinic {name} desk. Facts: {FACTS[name]} {RULES} {PEERS} {HANDOFF_RULE}\")\n         for name in FACTS}\n\n\ndef swarm(message: str, start: str = \"scheduling\") -> tuple[str, list[str]]:\n    guard, current, task = RunGuard(max_model_calls=6, max_depth=4), start, message\n    path = [start]\n    try:\n        while True:\n            guard.model_call(current)\n            reply = desks[current].run(task)\n            if not reply.startswith(\"HANDOFF:\"):\n                return reply, path\n            target, _, note = reply.removeprefix(\"HANDOFF:\").partition(\"|\")\n            current, task = target.strip(), f\"Patient asked: {message}\\nNote from {path[-1]} desk: {note.strip()}\"\n            guard.hand_off(current)\n            path.append(current)\n    except StopRun as stop:\n        return f\"Passing you to the front desk. ({stop})\", path\n\n\nif __name__ == \"__main__\":\n    for q in [\"Which days does Dr Iyer work?\", \"Is my knee surgery pre-authorisation needed if I use PM-JAY?\"]:\n        reply, path = swarm(q)\n        print(f\"{q}\\n  path: {' -> '.join(path)}\\n  reply: {reply}\\n\")\n","ch22/parallel_debate.py":"\"\"\"Two more patterns.\n\nPARALLEL  several specialists work on the same request AT THE SAME TIME; a combiner merges the answers\nDEBATE    a drafter writes, a critic with a different job challenges it, the drafter revises (max N rounds)\n\nRun:  python parallel_debate.py\n\"\"\"\nimport asyncio\nimport json\nimport time\n\nfrom agents import SPECIALISTS, Agent\n\ncombiner = Agent(\"combiner\", \"Combine the desk answers into one short reply for the patient. Keep every fact; \"\n                             \"do not add any.\")\ndrafter = Agent(\"drafter\", \"You write short, kind replies for City Clinic patients. Never give medical advice.\")\ncritic = Agent(\"critic\", 'You are the clinic\\'s patient-safety reviewer. Check the draft. Reply with JSON only: '\n                         '{\"approved\": true|false, \"problems\": [\"...\"]}. Reject any medical advice, any promise '\n                         'only a doctor can make, and any delay for possible emergencies.')\n\n\nasync def parallel(message: str, desks: list[str]) -> str:\n    start = time.perf_counter()\n    answers = await asyncio.gather(*(SPECIALISTS[d].arun(message) for d in desks))   # all at once\n    print(f\"  {len(desks)} desks answered in parallel in {time.perf_counter() - start:.2f}s\")\n    notes = \"\\n\".join(f\"{d}: {a}\" for d, a in zip(desks, answers))\n    return combiner.run(f\"Patient: {message}\\n\\nDesk answers:\\n{notes}\")\n\n\ndef debate(message: str, rounds: int = 2) -> tuple[str, int]:\n    draft = drafter.run(message)\n    for r in range(1, rounds + 1):\n        verdict = json.loads(critic.run(f\"Patient message: {message}\\nDraft reply: {draft}\"))\n        print(f\"  round {r}: approved={verdict['approved']} problems={verdict['problems']}\")\n        if verdict[\"approved\"]:\n            return draft, r\n        draft = drafter.run(f\"Patient message: {message}\\nYour draft: {draft}\\nFix these problems: {verdict['problems']}\")\n    return \"Let me connect you with a nurse who can help.\", rounds         # no agreement: hand over\n\n\nif __name__ == \"__main__\":\n    print(\"PARALLEL\")\n    msg = \"I need a cardiologist on Thursday and want to know if PM-JAY covers the visit and what the fee is.\"\n    print(\"  ->\", asyncio.run(parallel(msg, [\"scheduling\", \"insurance\", \"billing\"])))\n\n    print(\"\\nDEBATE\")\n    reply, used = debate(\"I've had a mild headache for 3 days, which tablet should I take before Dr Mehta's visit?\")\n    print(f\"  final after {used} round(s): {reply}\")\n","ch22/sequential_router.py":"\"\"\"Two basic patterns.\n\nSEQUENTIAL  intake -> specialist -> reviewer      a fixed assembly line; each agent's output feeds the next\nROUTER      supervisor picks ONE specialist       (the supervisor pattern's simplest form)\n\nRun:  python sequential_router.py\n\"\"\"\nimport json\n\nfrom agents import SPECIALISTS, Agent\n\nintake = Agent(\"intake\", \"Rewrite the patient's message as one clear request for a hospital desk. \"\n                         \"Remove personal details such as phone numbers. Reply with the request only.\")\nreviewer = Agent(\"reviewer\", \"You check replies from a hospital helpdesk before they are sent. If the reply gives \"\n                             \"medical advice or promises something staff must approve, rewrite it safely. \"\n                             \"Otherwise return it unchanged. Reply with the final text only.\")\nsupervisor = Agent(\"supervisor\", 'Route the patient request to one desk. Reply with JSON only: {\"desk\": '\n                                 '\"scheduling\" | \"billing\" | \"insurance\" | \"none\", \"reason\": \"...\"}')\n\n\ndef sequential(message: str, desk: str) -> list[tuple[str, str]]:\n    \"\"\"Fixed order, chosen by the developer. Simple and predictable.\"\"\"\n    steps = [(\"intake\", intake.run(message))]\n    steps.append((desk, SPECIALISTS[desk].run(steps[-1][1])))\n    steps.append((\"reviewer\", reviewer.run(f\"Request: {steps[0][1]}\\nReply: {steps[-1][1]}\")))\n    return steps\n\n\ndef route(message: str) -> tuple[str, str]:\n    \"\"\"The supervisor reads the request and picks who answers. Unknown -> a person.\"\"\"\n    decision = json.loads(supervisor.run(message))\n    desk = decision.get(\"desk\")\n    if desk not in SPECIALISTS:\n        return \"front desk\", \"I'll connect you with our front desk (1800-000-000).\"\n    return desk, SPECIALISTS[desk].run(message)\n\n\nif __name__ == \"__main__\":\n    print(\"SEQUENTIAL\")\n    for agent, text in sequential(\"hi my no is 9876543210, my son has fever, can I get the kids doctor on wed??\", \"scheduling\"):\n        print(f\"  {agent:<11}-> {text}\")\n\n    print(\"\\nROUTER\")\n    for msg in [\"Is the OPD fee refundable?\", \"Does PM-JAY cover gloves and syringes?\", \"Can I bring my dog?\"]:\n        desk, reply = route(msg)\n        print(f\"  {msg}\\n    -> {desk}: {reply}\")\n","common/llm.py":"\"\"\"One small helper so every chapter can call OpenAI or Anthropic the same way.\n\nChoose the provider in .env:   PROVIDER=openai   or   PROVIDER=anthropic\nOverride models if you like:   OPENAI_MODEL=...  ANTHROPIC_MODEL=...\n\n    from llm import chat, stream, achat\n    reply = chat(\"What are OPD timings?\", system=\"You are the City Clinic helpdesk.\")\n    print(reply[\"text\"], reply[\"input_tokens\"], reply[\"output_tokens\"])\n\"\"\"\nimport os\n\nfrom dotenv import load_dotenv\n\nload_dotenv()\nPROVIDER = os.getenv(\"PROVIDER\", \"openai\")\nMODELS = {\"openai\": os.getenv(\"OPENAI_MODEL\", \"gpt-4.1-mini\"),\n          \"anthropic\": os.getenv(\"ANTHROPIC_MODEL\", \"claude-haiku-5-5\")}\nTIMEOUT = float(os.getenv(\"LLM_TIMEOUT\", \"30\"))   # seconds per request; the SDK default is minutes\nRETRIES = int(os.getenv(\"LLM_RETRIES\", \"2\"))       # the SDKs retry rate limits and server errors for you\n_clients = {}\n\n\ndef _client(provider: str, use_async: bool = False):\n    key = (provider, use_async)\n    if key not in _clients:\n        if provider == \"openai\":\n            import openai\n            cls = openai.AsyncOpenAI if use_async else openai.OpenAI\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n        else:\n            import anthropic\n            cls = anthropic.AsyncAnthropic if use_async else anthropic.Anthropic\n            _clients[key] = cls(timeout=TIMEOUT, max_retries=RETRIES)\n    return _clients[key]\n\n\ndef _openai_messages(user, system, history):\n    msgs = [{\"role\": \"system\", \"content\": system}] if system else []\n    return msgs + list(history or []) + [{\"role\": \"user\", \"content\": user}]\n\n\ndef _anthropic_args(user, system, history, temperature, max_tokens, model):\n    args = {\"model\": model, \"max_tokens\": max_tokens,\n            \"messages\": list(history or []) + [{\"role\": \"user\", \"content\": user}]}\n    if system:\n        args[\"system\"] = system\n    # `temperature` is accepted so both providers share one call shape, but it is NOT sent to Anthropic: the\n    # current anthropic SDK (1.x and later) raises TypeError if you pass it. OpenAI still honours it.\n    return args\n\n\ndef chat(user: str, system: str | None = None, history: list | None = None,\n         temperature: float | None = None, max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Send one message (plus optional earlier history). Returns text and token counts.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, history), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = _client(provider).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = _client(provider).messages.create(**_anthropic_args(user, system, history, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\ndef stream(user: str, system: str | None = None, history: list | None = None,\n           max_tokens: int = 800, provider: str | None = None):\n    \"\"\"Yield the reply a few words at a time, as the model writes it.\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        chunks = _client(provider).chat.completions.create(\n            model=model, messages=_openai_messages(user, system, history), max_completion_tokens=max_tokens, stream=True)\n        for chunk in chunks:\n            if chunk.choices and chunk.choices[0].delta.content:\n                yield chunk.choices[0].delta.content\n    else:\n        with _client(provider).messages.stream(**_anthropic_args(user, system, history, None, max_tokens, model)) as s:\n            yield from s.text_stream\n\n\nasync def achat(user: str, system: str | None = None, temperature: float | None = None,\n                max_tokens: int = 800, provider: str | None = None) -> dict:\n    \"\"\"Async version of chat(), for running many calls at the same time (Chapter 4).\"\"\"\n    provider = provider or PROVIDER\n    model = MODELS[provider]\n    if provider == \"openai\":\n        kwargs = {\"model\": model, \"messages\": _openai_messages(user, system, None), \"max_completion_tokens\": max_tokens}\n        if temperature is not None:\n            kwargs[\"temperature\"] = temperature\n        r = await _client(provider, use_async=True).chat.completions.create(**kwargs)\n        return {\"text\": r.choices[0].message.content, \"input_tokens\": r.usage.prompt_tokens,\n                \"output_tokens\": r.usage.completion_tokens, \"model\": model}\n    r = await _client(provider, use_async=True).messages.create(\n        **_anthropic_args(user, system, None, temperature, max_tokens, model))\n    return {\"text\": \"\".join(b.text for b in r.content if b.type == \"text\"), \"input_tokens\": r.usage.input_tokens,\n            \"output_tokens\": r.usage.output_tokens, \"model\": model}\n\n\n# ---------------------------------------------------------------- embeddings (Chapter 6 onwards)\n# Anthropic does not offer its own embedding model, so embeddings come from OpenAI or from a\n# free local model. Choose in .env:  EMBEDDINGS=openai  (default)  or  EMBEDDINGS=local\nEMBEDDINGS = os.getenv(\"EMBEDDINGS\", \"openai\")\nEMBED_MODELS = {\"openai\": os.getenv(\"OPENAI_EMBED_MODEL\", \"text-embedding-3-small\"),\n                \"local\": os.getenv(\"LOCAL_EMBED_MODEL\", \"all-MiniLM-L6-v2\")}\n\n\ndef embed(texts: list[str], kind: str | None = None) -> list[list[float]]:\n    \"\"\"Turn each text into a vector of numbers that represents its meaning.\"\"\"\n    kind = kind or EMBEDDINGS\n    if kind == \"openai\":\n        r = _client(\"openai\").embeddings.create(model=EMBED_MODELS[\"openai\"], input=texts)\n        return [d.embedding for d in r.data]\n    if \"local\" not in _clients:                     # pip install sentence-transformers (downloads ~90 MB once)\n        from sentence_transformers import SentenceTransformer\n        _clients[\"local\"] = SentenceTransformer(EMBED_MODELS[\"local\"])\n    return _clients[\"local\"].encode(texts, normalize_embeddings=True).tolist()\n","common/requirements.txt":"# Pinned versions the course code was tested with. Install with: pip install -r requirements.txt\nopenai==3.43.0\nanthropic==2.4.0\npython-dotenv>=1.0\npydantic==2.13.5\ntiktoken>=0.8            # Chapter 2\nfastapi==0.162.0         # Chapter 5\nuvicorn>=0.30\npython-multipart>=0.0.9\nhttpx>=0.27\nstreamlit==1.66.1\ngradio==6.31.0\npytest>=8\n\n# Part C: frameworks and protocols (tested versions)\nlangchain==1.4.8                 # Chapters 12-13\nlangchain-core==1.7.4\nlangchain-openai==1.7.3\nlangchain-anthropic==1.7.9\nlangchain-community==0.4.2\nlangchain-text-splitters==1.1.3\nlangchain-classic==1.0.8         # only for legacy examples (AgentExecutor, old retrievers)\nlanggraph==1.2.19                # Chapters 14-15\nlanggraph-checkpoint-sqlite==3.1.3\nmcp==1.30.0                      # Chapters 16-17\nlangchain-mcp-adapters==0.3.2\nnetworkx==3.7                    # Chapter 18 (GraphRAG)\nchromadb==1.5.9                  # Chapters 6, 18, 19\nagno==3.1.12                     # Chapter 19\n# Optional: langchain-tavily, wikipedia, langchain-experimental (Chapter 13 built-in tools)\n# DSPy (Chapter 20) goes in a separate environment: see ch20/requirements-dspy.txt\n\n# Part D: multi-agent\n# CrewAI (Chapter 24) and AutoGen (Chapter 25) need their own environments: ch24/requirements-crewai.txt, ch25/requirements-autogen.txt\na2a-sdk==1.3.0                   # Chapter 26 (agent interoperability)\nfastapi==0.162.0\nuvicorn==0.54.0\n"});
